package com.nopilot.aiservice.model;  import java.nio.charset.StandardCharsets; import java.util.UUID;  /**  * A meaningful piece of one source file. Lines are 1-based and inclusive.  * "symbol" is the first class/function name found in the chunk (may be null).  */ public record CodeChunk(         String filePath,         String language,         int chunkIndex,         int startLine,         int endLine,         String symbol,         String content,         String contentHash ) {      /**      * Deterministic ID: re-embedding the same chunk overwrites the same vector row      * instead of creating a duplicate.      */     public String id(UUID repositoryId) {         String key = repositoryId + "|" + filePath + "|" + chunkIndex + "|" + contentHash;         return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();     } }
